def process_payment(idempotency_key, amount):
    import json

    cache_key = f"idemp:{idempotency_key}"
    pending = "__charge_in_progress__"

    def decode(value):
        if isinstance(value, (bytes, bytearray)):
            value = value.decode("utf-8")
        return json.loads(value) if isinstance(value, str) else value

    if not redis.set(cache_key, pending, nx=True, ex=120):
        return decode(redis.get(cache_key))

    receipt = stripe.Charge.create(amount=amount)
    redis.set(cache_key, json.dumps(receipt), ex=120)
    return receipt

